import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';import '../controllers/productos_controller.dart';import '../widgets/producto_form.dart';import '../widgets/producto_table.dart';import '../widgets/producto_actions.dart';class ProductosScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const ProductosScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<ProductosScreen> createState() => _ProductosScreenState();}class _ProductosScreenState extends State<ProductosScreen> {  final _controller = ProductosController();  @override  void initState() {    super.initState();    _controller.addListener(() => setState(() {}));    _controller.cargarProductos();  }  @override  void dispose() {    _controller.dispose();    super.dispose();  }  void _abrirFormulario({dynamic existente}) {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => ProductoForm(        existente: existente,        onSubmit: (producto) async {          if (existente != null) {            await _controller.actualizarProducto(producto);          } else {            await _controller.crearProducto(producto);          }          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              SnackBar(content: Text(existente != null ? 'Producto actualizado' : 'Producto creado')),            );          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Productos',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildContent() {    if (_controller.isLoading) {      return const Center(child: CircularProgressIndicator());    }    if (_controller.error != null) {      return Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            const Icon(Icons.error_outline, size: 48, color: AppColors.negativeRed),            const SizedBox(height: 16),            Text('Error: ${_controller.error}', style: const TextStyle(color: AppColors.textPrimary)),            const SizedBox(height: 16),            ElevatedButton(              onPressed: _controller.cargarProductos,              child: const Text('Reintentar'),            ),          ],        ),      );    }    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        PageHeader(          title: 'Gestión de Productos',          count: _controller.productos.length,          buttonLabel: 'Nuevo Producto',          onButtonPressed: () => _abrirFormulario(),        ),        const SizedBox(height: 20),        if (_controller.productos.isEmpty)          Container(            padding: const EdgeInsets.all(40),            decoration: BoxDecoration(              color: AppColors.cardBg,              borderRadius: BorderRadius.circular(16),              border: Border.all(color: AppColors.cardBorder),            ),            child: const Center(              child: Text('No hay productos', style: TextStyle(color: AppColors.textSecondary)),            ),          )        else          ProductoTable(              productos: _controller.productos,              onEdit: (p) => _abrirFormulario(existente: p),              onDelete: (p) => ProductoActions.confirmarEliminar(context, p, () async {                try {                  await _controller.eliminarProducto(p.id);                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Producto eliminado')));                  }                } catch (e) {                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.negativeRed),                    );                  }                }              }),            ),      ],    );  }}